(() => {
  const bc = document.querySelector('.o_breadcrumb');
  const btns = Array.from(document.querySelectorAll('.o_control_panel button, .o_cp_buttons button, button')).slice(0,25).map(b => ({t:(b.innerText||b.getAttribute('aria-label')||'').trim().slice(0,40), dis:b.disabled, cls:b.className.slice(0,60)}));
  return {bc: bc ? bc.innerText.replace(/\n+/g,'|') : null, dirty: !!document.querySelector('.o_form_dirty'), notifs: Array.from(document.querySelectorAll('.o_notification')).map(n=>n.innerText.slice(0,120)), btns};
})()
